import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useSearchParams } from "react-router-dom";
import { Bot, MapPinned, Sparkles } from "lucide-react";
import { useAppState } from "../state/AppState";
import { mergeClinics } from "../lib/clinics";
import MissionForm from "../components/MissionForm";
import AgentFeed from "../components/AgentFeed";
import ClinicMap from "../components/ClinicMap";
import ClinicCard from "../components/ClinicCard";
import ApplyModal from "../components/ApplyModal";
import ErrorBoundary from "../components/ErrorBoundary";

function EmptyState() {
  const steps = [
    { icon: MapPinned, title: "Find the clinics", text: "Searches your city for family practices." },
    { icon: Bot, title: "Read every website", text: "Agents check who's accepting new patients." },
    { icon: Sparkles, title: "Rank them for you", text: "Sorted for your coverage, language and distance." },
  ];
  return (
    <div className="card p-8">
      <h2 className="text-xl font-bold">Your results will appear here</h2>
      <p className="mt-1 text-sm text-slate-500">
        Press <b className="text-ink">Launch CareScout</b> to start. A live search takes a few minutes; Demo mode shows saved results instantly.
      </p>
      <ol className="mt-6 grid gap-4 sm:grid-cols-3">
        {steps.map(({ icon: Icon, title, text }, i) => (
          <li key={title} className="rounded-xl bg-slate-50 p-4">
            <div className="flex items-center gap-2 text-sm font-semibold text-ink">
              <span className="flex h-6 w-6 items-center justify-center rounded-full bg-ink text-xs text-white">{i + 1}</span>
              {title}
            </div>
            <div className="mt-2 flex items-start gap-2 text-xs text-slate-500">
              <Icon className="h-4 w-4 shrink-0 text-pine-600" />
              {text}
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
}

export default function FindPage() {
  const { search, setSearch, mission, launch, refreshWatchCount, publicDemo } = useAppState();
  const { state, stop, reset } = mission;
  const [params, setParams] = useSearchParams();
  const [selectedUrl, setSelectedUrl] = useState(null);
  const [applyFor, setApplyFor] = useState(null);
  const cardRefs = useRef({});
  const email = search.email.trim();

  const clinics = useMemo(() => mergeClinics(state.scanned, state.urls, state.ranked), [state.scanned, state.urls, state.ranked]);

  // /find?demo=1 (from the home page): switch on Demo mode and run it straight away (once).
  const demoStarted = useRef(false);
  useEffect(() => {
    if (params.get("demo") === "1" && !demoStarted.current) {
      demoStarted.current = true;
      setParams({}, { replace: true });
      setSearch((s) => ({ ...s, useCache: true }));
      if (!state.running) launch({ useCache: true });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onLaunch = () => {
    setSelectedUrl(null);
    launch();
  };

  const selectClinic = useCallback((url) => {
    setSelectedUrl(url);
    cardRefs.current[url]?.scrollIntoView({ behavior: "smooth", block: "nearest" });
  }, []);

  return (
    <div className="container-page space-y-4 py-8">
      <div className="mb-2">
        <h1 className="text-3xl font-bold tracking-tight">Find a family doctor</h1>
        <p className="mt-1 text-slate-500">Tell CareScout where you are and what you need. Agents check each clinic's website for you.</p>
      </div>

      <MissionForm values={search} onChange={setSearch} onLaunch={onLaunch} onStop={stop} running={state.running} publicDemo={publicDemo} />
      <AgentFeed state={state} onStop={stop} onReset={reset} />

      {clinics.length > 0 ? (
        <div className="grid grid-cols-1 gap-4 lg:grid-cols-5">
          <div className="min-w-0 lg:col-span-2">
            <div className="h-[360px] lg:sticky lg:top-24 lg:h-[calc(100vh-8rem)]">
              <ErrorBoundary label="The map">
                <ClinicMap clinics={clinics} selectedUrl={selectedUrl} onSelect={selectClinic} />
              </ErrorBoundary>
            </div>
          </div>
          <div className="min-w-0 space-y-3 lg:col-span-3">
            {clinics.map((c) => (
              <ErrorBoundary key={c.url} label={`The card for ${c.name || c.url}`}>
                <ClinicCard
                  ref={(el) => (cardRefs.current[c.url] = el)}
                  clinic={c}
                  selected={c.url === selectedUrl}
                  onSelect={setSelectedUrl}
                  onApply={setApplyFor}
                  email={email}
                  city={search.city}
                  onWatched={refreshWatchCount}
                />
              </ErrorBoundary>
            ))}
          </div>
        </div>
      ) : (
        !state.running && state.log.length === 0 && <EmptyState />
      )}

      {applyFor && <ApplyModal clinic={applyFor} defaults={search} onClose={() => setApplyFor(null)} />}
    </div>
  );
}
import { forwardRef, useState } from "react";
import { BellPlus, Check, Clock, ExternalLink, FileSignature, Loader2, MapPin, Phone, Quote, RefreshCw, ShieldCheck } from "lucide-react";
import { api } from "../api";
import { checkedLabel, displayStatus, isFailedScan, lastSeenLabel } from "../lib/clinics";
import { useAppState } from "../state/AppState";
import StatusBadge from "./StatusBadge";
import CallScript from "./CallScript";
import VerifyDoctor from "./VerifyDoctor";

function ScoreRing({ score }) {
  if (score == null) return null;
  const color = score >= 70 ? "text-emerald-600" : score >= 40 ? "text-amber-500" : "text-rose-500";
  const r = 18;
  const c = 2 * Math.PI * r;
  return (
    <div className="relative h-12 w-12 shrink-0" title={`Match score ${score}/100`}>
      <svg viewBox="0 0 44 44" className="h-12 w-12 -rotate-90">
        <circle cx="22" cy="22" r={r} fill="none" stroke="currentColor" strokeWidth="4" className="text-slate-100" />
        <circle cx="22" cy="22" r={r} fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round"
          strokeDasharray={c} strokeDashoffset={c * (1 - score / 100)} className={color} />
      </svg>
      <span className="absolute inset-0 flex items-center justify-center text-sm font-semibold text-slate-800">{score}</span>
    </div>
  );
}

/** One clinic: scan + ranking data, and its actions (apply / call / verify doctor / watch). */
const ClinicCard = forwardRef(function ClinicCard({ clinic, selected, onSelect, onApply, email, city, onWatched }, ref) {
  const [panel, setPanel] = useState(null); // "call" | "verify" | null
  const [watchEmail, setWatchEmail] = useState("");
  const [watchState, setWatchState] = useState({ loading: false, done: false, error: null, askEmail: false });
  const { publicDemo, search, mission } = useAppState();
  const [recheck, setRecheck] = useState({ loading: false, note: null, error: null });
  const checked = checkedLabel(clinic);
  const lastSeen = lastSeenLabel(clinic);
  const failed = isFailedScan(clinic);
  const status = displayStatus(clinic);
  const host = String(clinic.url).replace(/^https?:\/\/(www\.)?/, "").split("/")[0];

  const toggle = (p) => setPanel((cur) => (cur === p ? null : p));

  // Re-check this one clinic now (quick page read; a browser agent if the site needs one).
  const recheckNow = async () => {
    setRecheck({ loading: true, note: null, error: null });
    try {
      const r = await api.refreshClinic(clinic.url, city, search.postalCode);
      mission.updateClinic(r.clinic);
      const note = r.method === "failed" ? `Couldn't re-check right now (${r.error}). Showing the last saved result.`
        : r.status_changed ? "Status changed since the last check." : r.method === "unchanged" ? "No change on the clinic's website." : "Up to date.";
      setRecheck({ loading: false, note, error: null });
    } catch (e) {
      setRecheck({ loading: false, note: null, error: e.message });
    }
  };

  const watch = async () => {
    const userEmail = (email || watchEmail).trim();
    if (!userEmail.includes("@")) {
      setWatchState((s) => ({ ...s, askEmail: true, error: userEmail ? "Enter a valid email." : null }));
      return;
    }
    setWatchState({ loading: true, done: false, error: null, askEmail: false });
    try {
      await api.addWatch(clinic, userEmail);
      setWatchState({ loading: false, done: true, error: null, askEmail: false });
      onWatched?.(userEmail);
    } catch (e) {
      setWatchState({ loading: false, done: false, error: e.message, askEmail: true });
    }
  };

  return (
    <article
      ref={ref}
      onClick={() => onSelect(clinic.url)}
      className={`card scroll-mt-24 p-4 transition ${selected ? "ring-2 ring-emerald-500" : "hover:border-slate-300"}`}
    >
      <div className="flex items-start gap-3">
        <ScoreRing score={clinic.score} />
