  transform: scaleX(0);
  transition: transform 1.4s cubic-bezier(0.65, 0, 0.35, 1) 0.15s;
}
[data-shown] .flow-line,
.flow-line[data-shown] {
  transform: scaleX(1);
}
.flow-rail {
  transform-origin: top center;
