export default function WatchdogView({ email, onEmail, onAlert, onChanged }) {
  const { publicDemo } = useAppState();
  const [watches, setWatches] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [checking, setChecking] = useState(false);
  const [simulating, setSimulating] = useState(false);
  const [message, setMessage] = useState(null);
  const [error, setError] = useState(null);
  const userEmail = email.includes("@") ? email.trim() : undefined;

  const load = useCallback(async () => {
    setError(null);
    try {
      const [w, a] = await Promise.all([api.listWatches(userEmail), api.watchAlerts(userEmail, 10)]);
      setWatches(w.watched_clinics);
      setAlerts(a.alerts);
      onChanged?.(w.watched_clinics.length);
    } catch (e) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, [userEmail, onChanged]);

  useEffect(() => {
    load();
  }, [load]);

  const checkAll = async () => {
    setChecking(true);
    setMessage(null);
    setError(null);
    try {
      const r = await api.checkWatches(userEmail);
      setMessage(`Checked ${r.checked} clinic${r.checked === 1 ? "" : "s"}${r.failed ? ` (${r.failed} couldn't be checked)` : ""}. ${r.alerts.length ? `${r.alerts.length} changed!` : "No changes yet."}`);
      if (r.alerts[0]) onAlert(r.alerts[0]);
      await load();
    } catch (e) {
      setError(e.message);
    } finally {
      setChecking(false);
    }
  };

  const simulate = async (watchId) => {
    setSimulating(true);
    setError(null);
    try {
      const r = await api.simulateOpening(watchId);
      onAlert(r.alert);
      await load();
    } catch (e) {
      setError(e.message);
    } finally {
      setSimulating(false);
    }
  };

  const remove = async (w) => {
    if (!userEmail) {
      setError("Enter your email above to manage your watches.");
      return;
    }
    try {
      await api.deleteWatch(w.id, userEmail);
      await load();
    } catch (e) {
      setError(e.message);
    }
  };

  return (
    <div className="space-y-4">
      <section className="card p-4">
        <div className="flex flex-wrap items-end justify-between gap-3">
          <div className="flex flex-wrap items-end gap-2">
            <div>
              <label className="label" htmlFor="wd-email">Your email</label>
              <input id="wd-email" type="email" className="input w-64 max-w-full" value={email} onChange={(e) => onEmail(e.target.value)} placeholder="you@example.com" />
            </div>
            <button onClick={checkAll} disabled={checking || watches.length === 0 || publicDemo} className="btn-primary" title={publicDemo ? "Live checks are off on the public demo" : undefined}>
              {checking ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />} Check All Now
            </button>
          </div>
        </div>
        {!userEmail && <p className="mt-2 text-xs text-amber-700">Showing everyone's watches with emails hidden. Enter your email to see only yours.</p>}
        {publicDemo && <p className="mt-2 text-xs text-slate-500">Live re-checks are turned off on this public demo. Use Simulate Opening to see how an alert looks.</p>}
        {checking && <p className="mt-2 text-xs text-slate-500">Agents are re-checking each clinic's website. This takes a few minutes.</p>}
        {message && <p className="mt-2 text-sm text-emerald-700">{message}</p>}
        {error && <p className="mt-2 text-sm text-rose-700">{error}</p>}
      </section>

      <section className="card divide-y divide-slate-100">
// The one place to change backend settings. Override without editing code by creating
// frontend/.env.local with e.g.  VITE_API_URL=http://localhost:8000  (and VITE_API_KEY=... if the
// backend has CARESCOUT_API_KEY set).
// A value without "https://" (e.g. "my-api.up.railway.app") would otherwise be treated as a path on the website itself,
// so every API call would hit the website instead of the backend (POST -> 405). Add the scheme if it's missing.
export function normalizeApiUrl(raw) {
  let url = String(raw || "http://localhost:8000").trim().replace(/\/+$/, "");
  if (!/^https?:\/\//i.test(url)) url = (/^(localhost|127\.0\.0\.1)(:|$)/.test(url) ? "http://" : "https://") + url;
  return url;
}
export const API_BASE_URL = normalizeApiUrl(import.meta.env.VITE_API_URL);
