import { useEffect, useState } from "react";
import Topography from "../bits/Topography";
import { useIsDark } from "../../theme";

/** WebGL2 available, a screen wide enough to see it, and the person hasn't asked to save data. */
function canShow() {
  if (typeof window === "undefined") return false;
  if (!window.matchMedia?.("(min-width: 768px)").matches) return false;
  if (navigator.connection?.saveData) return false;
  try {
    return !!document.createElement("canvas").getContext("webgl2");
  } catch {
    return false;
  }
}

/**
 * The hero's backdrop: a slowly drifting contour map in pine (React Bits Topography), the terrain CareScout searches
 * for you. Purely decorative: fades out toward the text, ignores the pointer, and isn't drawn on phones, without
 * WebGL2, or with Data Saver on. Reduced motion is handled inside Topography (it holds still).
 */
export default function HeroTerrain() {
  const dark = useIsDark();
  const [show, setShow] = useState(false);
  useEffect(() => setShow(canShow()), []);
  if (!show) return null;
  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute inset-0 -z-10 animate-fade-in [animation-duration:1.6s] [mask-image:radial-gradient(120%_90%_at_70%_40%,#000_35%,transparent_80%)]"
    >
      <Topography
        key={dark ? "dark" : "light"}
        color={dark ? "#62BB99" : "#23876C"}
        lightMode={!dark}
        opacity={dark ? 0.55 : 0.45}
        lineCount={24}
        lineWidth={1}
        speed={0.12}
        morph={0.15}
        tilt={38}
        glow={dark ? 0.5 : 0.25}
        fog={0.45}
        markers="dots"
        mouseInteraction={false}
        clickEffect="none"
        dpr={Math.min(window.devicePixelRatio || 1, 1.5)}
      />
    </div>
  );
}

import { useEffect, useState } from "react";
import { api } from "../../api";
import { displayStatus } from "../../lib/clinics";
import CountUp from "../CountUp";

/**
 * One honest sentence from the live clinic database: how many London clinics CareScout tracks and how many say, on
 * their own website, that they take new patients. Uses the same list a search shows (no directories, one entry per
 * clinic website, nothing whose status is too old to trust). Hidden if the backend can't be reached.
 */
export default function LiveTally() {
  const [tally, setTally] = useState(null);

  useEffect(() => {
    let live = true;
    api
      .listClinics("London, ON", null, 25)
      .then((r) => {
        if (!live || !r.clinics?.length) return;
        const current = r.clinics.filter((c) => !c.expired && displayStatus(c) !== "unknown");
        setTally({ total: r.clinics.length, accepting: current.filter((c) => c.status === "accepting").length });
      })
      .catch(() => {});
    return () => {
      live = false;
    };
  }, []);

  if (!tally) return <p className="mt-6 h-6" aria-hidden="true" />;
  return (
    <p className="mt-6 animate-fade-in text-sm text-slate-600">
      Right now CareScout tracks <CountUp value={tally.total} className="font-semibold text-ink" /> London clinics, and{" "}
      <CountUp value={tally.accepting} className="font-semibold text-pine-700" /> of them say on their own website that they're taking new patients.
    </p>
  );
}

